using MySqlConnector;
namespace WoWItemEditor;
internal static class QuestAvailability
{
    internal static async Task<string> Check(QuestDraft draft,CharacterInfo hero,int quest,int npc)
    {
        using var db=await DatabaseConnection.OpenAsync(QuestCreation.World);var rows=await WorldDrops.Query(db,null,$"SELECT guid,level,race,class FROM {AppSettings.Current.CharacterDatabase}.characters WHERE guid={hero.Guid}");var character=rows.Single();int level=int.Parse(character["level"]!),race=int.Parse(character["race"]!),cls=int.Parse(character["class"]!);var o=draft.Options;var lines=new List<string>{$"{hero.Name}: level {level}; quest level {draft.Level}, minimum {draft.MinLevel}"};
        if(level<draft.MinLevel)lines.Add("BLOCKED: character level is below the minimum.");else if(o.MaxLevel>0&&level>o.MaxLevel)lines.Add("BLOCKED: character level exceeds the maximum.");else lines.Add("Level requirement passes.");
        if(o.AutoAccept)lines.Add("Auto-accept is enabled; accepting automatically can replace the ! with quest-log / turn-in state.");
        if(draft.Level+5<level)lines.Add("The quest is much lower level: the ! may be hidden. Enable low-level / trivial quest tracking in WoW. The exact threshold depends on server settings.");
        if(o.Races!=ulong.MaxValue){if(race>64)lines.Add("Custom race restriction cannot be verified here; use All races unless you know its server mapping.");else if((o.Races&(1UL<<(race-1)))==0)lines.Add("BLOCKED: this race is excluded.");}
        if(o.Classes!=0&&(o.Classes&(1u<<(cls-1)))==0)lines.Add("BLOCKED: this class is excluded.");
        if(quest>0){if((await WorldDrops.Query(db,null,$"SELECT quest FROM {AppSettings.Current.CharacterDatabase}.character_queststatus_rewarded WHERE guid={hero.Guid} AND quest={quest} AND active=1")).Count>0)lines.Add(o.Repeat=="Once"?"BLOCKED: this character already completed this one-time quest.":"Previously rewarded; repeat availability depends on its reset schedule.");var active=await WorldDrops.Query(db,null,$"SELECT status FROM {AppSettings.Current.CharacterDatabase}.character_queststatus WHERE guid={hero.Guid} AND quest={quest}");if(active.Count>0)lines.Add("This character already has a quest-status record (status "+active[0]["status"]+"). A turn-in marker may replace the !.");}
        if(o.PreviousQuest>0&&(await WorldDrops.Query(db,null,$"SELECT quest FROM {AppSettings.Current.CharacterDatabase}.character_queststatus_rewarded WHERE guid={hero.Guid} AND quest={o.PreviousQuest} AND active=1")).Count==0)lines.Add("BLOCKED: prerequisite quest is not completed.");
        if(npc>0){var npcRows=await WorldDrops.Query(db,null,$"SELECT faction,npcflag FROM {QuestCreation.World}.creature_template WHERE entry={npc}");if(npcRows.Count==0)lines.Add("BLOCKED: quest giver is missing.");else{int faction=int.Parse(npcRows[0]["faction"]!);var factionRows=await ItemModelAssets.Shared.Table("FactionTemplate");var factions=await ItemModelAssets.Shared.Table("Faction");int factionId=factionRows.TryGetValue(faction,out var row)?TooltipData.Number(row,"Faction"):0;string name=factions.TryGetValue(factionId,out var definition)?definition.GetValueOrDefault("Name")??"Unnamed":"Unnamed";lines.Add("NPC faction: "+name+". It must be friendly enough to interact with your character; reputation and race can change its reaction.");if((ulong.Parse(npcRows[0]["npcflag"]!)&2)==0)lines.Add("BLOCKED: NPC lacks the quest-giver flag.");if(quest>0&&(await WorldDrops.Query(db,null,$"SELECT quest FROM {QuestCreation.World}.creature_queststarter WHERE id={npc} AND quest={quest}")).Count==0)lines.Add("BLOCKED: starter relation is missing.");}}
        if(o.RequiredSkill>0||o.RequiredRepFaction>0||o.ExclusiveGroup>0)lines.Add("Profession, reputation and exclusive-group conditions also apply.");lines.Add("This checks saved database data, not the live server cache. Restart the worldserver after edits; no settings can force ! for every player regardless of eligibility.");return string.Join("\n",lines);
    }
}
